css:
.nir-label { width: 62mm; padding: 2mm; border: 1px dashed #bbb; font-family: Arial, sans-serif; font-size: 8pt; line-height: 1.25; page-break-inside: avoid; margin-bottom: 3mm; }
.nir-label .nir-name { font-weight: bold; font-size: 9pt; }
.nir-label .nir-code { font-family: monospace; font-size: 9pt; text-align: center; letter-spacing: 0.5px; }
.nir-label img { width: 100%; height: 12mm; }
.nir-label .nir-meta { display: flex; justify-content: space-between; }
.nir-bin { width: 90mm; font-size: 10pt; }
.nir-bin .nir-name { font-size: 16pt; text-align: center; }
.nir-bin img { height: 18mm; }
